// 📌 n8n Code (JavaScript) — Run Once for All Items

// ---- pull inputs by node name ----
function getFrom(nodeName, path) {
  const arr = $items(nodeName, 0, 0);
  if (!arr || !arr[0]) throw new Error(`No data from node: ${nodeName}`);
  let obj = arr[0].json;
  for (const key of path) obj = obj?.[key];
  return obj;
}

const scenes = getFrom("No Operation, do nothing", ["message","content","scenes"]);
const segments = getFrom("Get word timing", ["segments"]);

if (!Array.isArray(scenes)) throw new Error("Scenes not found/array.");
if (!Array.isArray(segments)) throw new Error("Segments not found/array.");

// ---- flatten Whisper words timeline ----
const flatWords = [];
for (const seg of segments) {
  if (!Array.isArray(seg?.words)) continue;
  for (const w of seg.words) {
    if (w?.word == null) continue;
    flatWords.push({
      raw: String(w.word),
      norm: normToken(w.word),
      start: Number(w.start),
      end: Number(w.end),
    });
  }
}

function normToken(s) {
  return String(s)
    .toLowerCase()
    .replace(/['’]/g, "")           // today's -> todays
    .replace(/[^0-9\p{L}]+/gu, ""); // drop punctuation/spaces
}

function tokenize(text) {
  return String(text)
    .split(/\s+/)
    .map(normToken)
    .filter(Boolean);
}

// strict consecutive match; returns [startIdx, endIdx] or null
function strictFind(sceneTokens, wordsNorm) {
  for (let i = 0; i <= wordsNorm.length - sceneTokens.length; i++) {
    let ok = true;
    for (let j = 0; j < sceneTokens.length; j++) {
      if (wordsNorm[i + j] !== sceneTokens[j]) { ok = false; break; }
    }
    if (ok) return [i, i + sceneTokens.length - 1];
  }
  return null;
}

// lenient window: allow 1 mismatch within window of scene length
function fuzzyFind(sceneTokens, wordsNorm) {
  let best = null, bestScore = -Infinity;
  const L = sceneTokens.length;
  for (let i = 0; i <= wordsNorm.length - L; i++) {
    let matches = 0, mismatches = 0;
    for (let j = 0; j < L; j++) {
      if (wordsNorm[i + j] === sceneTokens[j]) matches++;
      else mismatches++;
      if (mismatches > 1) break;
    }
    const score = matches - mismatches;
    if (mismatches <= 1 && score > bestScore) {
      bestScore = score;
      best = [i, i + L - 1];
    }
  }
  return best;
}

// precompute normalized word list for searching
const wordsNorm = flatWords.map(w => w.norm);

// ---- compute timings per scene ----
const enriched = scenes.map(scene => {
  const text = scene?.voiceOverText ?? "";
  const tokens = tokenize(text);

  let span = tokens.length ? strictFind(tokens, wordsNorm) : null;
  if (!span) span = tokens.length ? fuzzyFind(tokens, wordsNorm) : null;

  if (span) {
    const [sIdx, eIdx] = span;
    return {
      ...scene,
      startTime: flatWords[sIdx].start,
      endTime: flatWords[eIdx].end,
    };
  } else {
    return { ...scene, startTime: null, endTime: null }; // no match
  }
});

// ---- output a single item with new scenes array ----
return [
  {
    json: {
      scenes: enriched,
      meta: {
        total: scenes.length,
        matched: enriched.filter(s => s.startTime != null).length,
      },
    },
  },
];

// Node that produced { scenes: [...] }
const PREV_NODE = "Set start and end time";

// Pull scenes from previous node
const prev = $items(PREV_NODE, 0, 0);
if (!prev || !prev[0]) throw new Error(`No data from node: ${PREV_NODE}`);
const scenes = Array.isArray(prev[0].json.scenes) ? prev[0].json.scenes : [];
if (!scenes.length) return [{ json: { scenes, meta: { total: 0 } } }];

// Optional tiny epsilon to avoid float glitches in some editors/encoders.
// Keep 0 for exact adjacency.
const EPS = 0;

// Keep original order, but we need a sorted copy to align by start
const withIdx = scenes.map((s, i) => ({ ...s, __i: i }));
const sorted = [...withIdx].sort((a, b) => {
  const as = Number.isFinite(a.startTime) ? a.startTime : Infinity;
  const bs = Number.isFinite(b.startTime) ? b.startTime : Infinity;
  return as === bs ? a.__i - b.__i : as - bs;
});

// Chain: end(i) = start(i+1), only when both starts exist
for (let i = 0; i < sorted.length - 1; i++) {
  const cur = sorted[i];
  const next = sorted[i + 1];

  if (Number.isFinite(cur.startTime) && Number.isFinite(next.startTime)) {
    // ensure non-negative duration
    const newEnd = Math.max(cur.startTime, next.startTime - EPS);
    cur.endTime = newEnd;
  }
}

// For any scene that still lacks an endTime, keep whatever it had
// (usually the last scene). No change needed.

// Restore original order
sorted.sort((a, b) => a.__i - b.__i);
const chained = sorted.map(({ __i, ...rest }) => {
  // Optional: round to ms to remove float noise
  const r = v => (Number.isFinite(v) ? Math.round(v * 1000) / 1000 : v);
  return { ...rest, startTime: r(rest.startTime), endTime: r(rest.endTime) };
});

return [
  {
    json: {
      scenes: chained,
      meta: {
        total: chained.length,
        chained: true,
      },
    },
  },
];

// Node that already outputs { scenes: [...] } with startTime/endTime
const PREV_NODE = "Align scene end times"; // <-- change if your node name differs

// fetch scenes
const prev = $items(PREV_NODE, 0, 0);
if (!prev || !prev[0]) throw new Error(`No data from node: ${PREV_NODE}`);
const scenes = Array.isArray(prev[0].json.scenes) ? prev[0].json.scenes : [];

// helper: round to milliseconds
const r = v => (Number.isFinite(v) ? Math.round(v * 1000) / 1000 : v);

let totalDuration = 0;
let missing = 0;

const withDurations = scenes.map(s => {
  const start = Number(s.startTime);
  const end = Number(s.endTime);

  let dur = null;
  if (Number.isFinite(start) && Number.isFinite(end)) {
    dur = Math.max(0, end - start); // never negative
    totalDuration += dur;
  } else {
    missing++;
  }

  return {
    ...s,
    startTime: r(start),
    endTime: r(end),
    totalTime: r(dur), // seconds
  };
});

return [{
  json: {
    scenes: withDurations,
    meta: {
      totalScenes: scenes.length,
      withDurations: scenes.length - missing,
      missingDurations: missing,
      totalDuration: r(totalDuration), // seconds
    },
  },
}];
